import{_ as n,o as h,c as o,a2 as c}from"./chunks/framework.2Es64uX1.js";const l=JSON.parse('{"title":"Đề xuất bổ sung bài kiểm tra hackathon 2-3 tuần (case study Hoàng Mai Toán và Dr May Day) cho KTPMUD","description":"","frontmatter":{"title":"Đề xuất bổ sung bài kiểm tra hackathon 2-3 tuần (case study Hoàng Mai Toán và Dr May Day) cho KTPMUD","document_id":"KTPMUD-HACKATHON-CASESTUDY-PROPOSAL","author_owner":"Dự án KTPMUD, fossbk-spec","reviewer":"Claude","version":"0.5.0","date":"2026-11-02","timezone":"Asia/Ho_Chi_Minh","status":"Proposal — chưa phải tính năng đã triển khai","language":"vi","repository":"fossbk-spec/KTPMUD","target_path":"docs/proposals/KTPMUD_Hackathon_CaseStudy_HoangMaiMath_DrMayDay_Proposal_v0.1.0_20261101.md","base_snapshot_KTPMUD":"e150d98ac90bc978a263f5a8257724f8185376d2","base_snapshot_ktpmud_project":"61d908662df6688a693f27853f5222dbce8dba12","supersedes":null,"related_review":"docs/reviews/KTPMUD_Hackathon_CaseStudy_AppChoice_Review_v1.0.0_20261101.md"},"headers":[],"relativePath":"proposals/KTPMUD_Hackathon_CaseStudy_HoangMaiMath_DrMayDay_Proposal_v0.1.0_20261101.md","filePath":"proposals/KTPMUD_Hackathon_CaseStudy_HoangMaiMath_DrMayDay_Proposal_v0.1.0_20261101.md","lastUpdated":1793578512000}'),i={name:"proposals/KTPMUD_Hackathon_CaseStudy_HoangMaiMath_DrMayDay_Proposal_v0.1.0_20261101.md"};function a(e,t,r,d,g,s){return h(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="đe-xuat-bo-sung-bai-kiem-tra-hackathon-2-3-tuan-cho-ktpmud-v0-5-0" tabindex="-1">Đề xuất bổ sung bài kiểm tra hackathon 2-3 tuần cho KTPMUD v0.5.0 <a class="header-anchor" href="#đe-xuat-bo-sung-bai-kiem-tra-hackathon-2-3-tuan-cho-ktpmud-v0-5-0" aria-label="Permalink to &quot;Đề xuất bổ sung bài kiểm tra hackathon 2-3 tuần cho KTPMUD v0.5.0&quot;">​</a></h1><h2 id="thong-tin-tai-lieu" tabindex="-1">Thông tin tài liệu <a class="header-anchor" href="#thong-tin-tai-lieu" aria-label="Permalink to &quot;Thông tin tài liệu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trường</th><th>Giá trị</th></tr></thead><tbody><tr><td>Phiên bản</td><td>0.5.0</td></tr><tr><td>Ngày</td><td>02/11/2026</td></tr><tr><td>Trạng thái</td><td>Proposal — chưa phải tính năng đã triển khai</td></tr><tr><td>Tác giả/chủ sở hữu</td><td>Dự án KTPMUD, fossbk-spec</td></tr><tr><td>Repo đích</td><td><code>fossbk-spec/KTPMUD</code> (và <code>ktpmud-project</code> cho phần nộp bài)</td></tr><tr><td>Snapshot KTPMUD</td><td><code>e150d98ac90bc978a263f5a8257724f8185376d2</code></td></tr><tr><td>Snapshot ktpmud-project</td><td><code>61d908662df6688a693f27853f5222dbce8dba12</code></td></tr></tbody></table><blockquote><p>Tài liệu mô tả phương án; case study, trang nội dung, rubric và CI mô tả dưới đây chưa tồn tại trong repo cho tới khi có PR tương ứng.</p><p><strong>v0.2.0 thay đổi so với v0.1.0:</strong> BKT-2 đổi app đích từ <code>hoang-mai-math</code> sang <code>math3a2</code>, sau 2 vòng đánh giá độc lập của Codex + tự kiểm chứng của Claude — xem <code>docs/reviews/KTPMUD_Hackathon_CaseStudy_AppChoice_Review_v1.0.0_20261101.md</code>. Mục 6 dưới đây đã viết lại hoàn toàn theo quyết định này.</p><p><strong>v0.3.0 thay đổi so với v0.2.0:</strong> thời lượng tăng 1-2 tuần → <strong>2-3 tuần</strong>, chạy <strong>song song với đồ án PBL</strong> (không tách riêng); mỗi nhóm chỉ chọn <strong>1 trong 2 track</strong> (không làm cả 2); thêm <strong>6 cơ chế gamification/cạnh tranh</strong> (đa giải, leaderboard công khai, demo công khai, peer review có điểm cộng, bộ test ẩn cho Track A, Hall of Fame trên <code>ktpmud-book</code>) — xem Mục 3, 5.3, 6.3, 6.4.</p><p><strong>v0.4.0 thay đổi so với v0.3.0:</strong> chốt toàn bộ 7 điểm còn mở ở Mục 10 (Claude quyết theo yêu cầu người dùng &quot;quyết luôn các câu hỏi mở còn lại&quot;, 1 điểm vẫn đánh dấu ⚠️ cần GV xác nhận lại lịch thật). Phát hiện quan trọng: đã kiểm tra trực tiếp <code>math3a2/data/seed.json</code> — repo đã có đủ 81 bài, toàn bộ chương trình SGK Toán 3, nên giả định ban đầu &quot;còn bài SGK thiếu để thêm&quot; ở Mục 6.2 là <strong>sai</strong>, đã sửa lại thành &quot;thêm 1 dạng bài mới&quot; (Mục 6.2, 10 điểm 3).</p><p><strong>v0.5.0 thay đổi so với v0.4.0:</strong> thay vì sửa trực tiếp <code>math3a2</code>, đã <strong>tạo 2 repo starter công khai riêng</strong> (snapshot đóng băng, không đụng <code>math3a2</code> thật): <a href="https://github.com/fossbk-spec/ktpmud-bkt-vuontoan-starter" target="_blank" rel="noreferrer"><code>fossbk-spec/ktpmud-bkt-vuontoan-starter</code></a> (Track B) và <a href="https://github.com/fossbk-spec/ktpmud-bkt-ruleengine-starter" target="_blank" rel="noreferrer"><code>fossbk-spec/ktpmud-bkt-ruleengine-starter</code></a> (Track A). Phát hiện khi dọn dữ liệu: tên + <strong>ảnh thật</strong> của giáo viên (<code>giaovien01</code>) không chỉ nằm ở <code>data/seed.json</code> mà còn hard-code làm giá trị mặc định trong nhiều file JS/HTML và bị server tự ghi đè vào DB mỗi lần khởi động — nghiêm trọng hơn đánh giá ban đầu, càng củng cố lý do không nên cho sinh viên làm việc trực tiếp trên <code>math3a2</code>. Xem Mục 6.1, 10 điểm 5.</p></blockquote><h2 id="_1-yeu-cau-goc" tabindex="-1">1. Yêu cầu gốc <a class="header-anchor" href="#_1-yeu-cau-goc" aria-label="Permalink to &quot;1. Yêu cầu gốc&quot;">​</a></h2><blockquote><p>&quot;Cập nhật bài giảng, xây dựng case study chung về hoang-mai-math và Dr May Day. Hai case study sẽ dùng làm bài kiểm tra cho sinh viên: có thể dùng AI, tài liệu về case study sẽ được cung cấp trước. Mỗi case study có thể trở thành hack marathon trong 1-2 tuần với MVP là sản phẩm đầu ra bắt buộc.&quot;</p></blockquote><h2 id="_2-hien-trang-—-vi-sao-can-mot-loai-case-study-moi-khong-sua-cs-1-cu" tabindex="-1">2. Hiện trạng — vì sao cần một LOẠI case study mới, không sửa CS-1 cũ <a class="header-anchor" href="#_2-hien-trang-—-vi-sao-can-mot-loai-case-study-moi-khong-sua-cs-1-cu" aria-label="Permalink to &quot;2. Hiện trạng — vì sao cần một LOẠI case study mới, không sửa CS-1 cũ&quot;">​</a></h2><p>KTPMUD hiện có 8 case study (<code>may_day</code>, <code>suy_tim</code>, <code>alzheimer</code>, <code>dreye</code>, <code>dai_thao_duong</code>, <code>nha_cho_thue</code>, <code>ban_do_lich_su</code>, <code>ke_hoach_hoc_tap</code>), tất cả dùng chung <strong>một khung duy nhất</strong>: đồ án môn học 10–12 tuần (PBL), SRS do sinh viên tự viết, rubric 100 điểm theo tiến độ sprint (<code>docs/do_an_mon_hoc.md</code>).</p><p>Yêu cầu mới <strong>không khớp khung này</strong> ở 3 điểm:</p><table tabindex="0"><thead><tr><th>Khung hiện có (CS-1..CS-8)</th><th>Yêu cầu mới</th></tr></thead><tbody><tr><td>10–12 tuần</td><td>1–2 tuần</td></tr><tr><td>Sinh viên tự khảo sát/viết SRS</td><td>Tài liệu case study cung cấp sẵn trước</td></tr><tr><td>Không nói rõ chính sách AI</td><td>Cho phép dùng AI công khai</td></tr><tr><td>Deliverable = hệ thống hoàn chỉnh + báo cáo</td><td>Deliverable = MVP bắt buộc</td></tr></tbody></table><p>→ Đề xuất: không sửa CS-1 (Dr May Day v2.0 bản PBL 10-12 tuần, đang dùng ổn định) — tạo <strong>một khung mới song song</strong>: &quot;Bài kiểm tra Hackathon&quot; (gọi tắt <code>BKT</code>), độc lập về trang nội dung, rubric và slug, nhưng <strong>dùng lại đúng</strong> cơ chế nộp bài qua PR + CI của <code>ktpmud-project</code> đã có sẵn (không xây hạ tầng mới).</p><h2 id="_3-khung-bai-kiem-tra-hackathon-bkt-—-nguyen-tac-thiet-ke" tabindex="-1">3. Khung &quot;Bài kiểm tra Hackathon&quot; (BKT) — nguyên tắc thiết kế <a class="header-anchor" href="#_3-khung-bai-kiem-tra-hackathon-bkt-—-nguyen-tac-thiet-ke" aria-label="Permalink to &quot;3. Khung &quot;Bài kiểm tra Hackathon&quot; (BKT) — nguyên tắc thiết kế&quot;">​</a></h2><ol><li><strong>Thời lượng:</strong> 2-3 tuần cho cả BKT-1 và BKT-2 (tăng từ 1-2 tuần ở v0.1.0/v0.2.0, theo quyết định 02/11/2026), chạy <strong>song song với đồ án PBL</strong> — không tách thành một khối riêng sau khi PBL kết thúc.</li><li><strong>Mỗi nhóm chỉ chọn 1 trong 2 track (BKT-1 HOẶC BKT-2), không làm cả hai.</strong> Vì vậy cả hai track chạy <strong>chung một cửa sổ thời gian</strong> (không cần tách lịch nối tiếp cho từng track) — khung này giống một hackathon thật có nhiều track song song hơn là 2 kỳ thi tuần tự.</li><li><strong>Đặt cửa sổ BKT vào Tuần 1-3 của PBL</strong> (không phải tuần bất kỳ): đồ án PBL CS-1 có Sprint riêng để sinh viên tự code Rule Engine WAO/EAACI (Tuần 4-6 ở nhánh &quot;MayDay-Sim&quot;, Tuần 6-7 ở nhánh &quot;Tích hợp thật&quot; — xem <code>docs/syllabus.md</code>). Nếu BKT-1 (cũng là Rule Engine) chạy trùng đúng Sprint đó, sinh viên có thể copy thẳng code PBL đang làm sang bài BKT, làm mất tính độc lập của bài kiểm tra. Đặt BKT ở Tuần 1-3 (lúc PBL mới làm SRS/ Checkpoint 1, chưa đụng code Rule Engine) tránh được việc này; BKT-2 không bị ràng buộc nội dung nên đặt cùng cửa sổ không có rủi ro tương tự.</li><li><strong>Tài liệu case study cung cấp trước</strong> — không phải sinh viên tự khảo sát. Mỗi BKT có 1 &quot;Đề bài + Data Dictionary + Acceptance Criteria&quot; công bố ngày mở đề, không thay đổi trong lúc thi (tương đương nguyên tắc &quot;protocol immutable sau khi duyệt&quot; đã dùng ở các case study khác).</li><li><strong>Chính sách AI công khai, không mập mờ:</strong> mỗi BKT khai báo rõ 1 trong 4 mức — <code>ai-required</code> / <code>ai-allowed</code> / <code>ai-limited</code> / <code>ai-prohibited</code> — và bắt buộc <strong>khai báo sử dụng AI</strong> trong bài nộp (tên công cụ, mục đích, phần nào do AI hỗ trợ). Không cấm AI nhưng không chấm điểm việc &quot;có dùng AI&quot; — chấm điểm sản phẩm và hiểu biết thật.</li><li><strong>MVP là deliverable bắt buộc, có định nghĩa cụ thể theo từng case</strong> — không chấp nhận &quot;chỉ có thiết kế/báo cáo, không có code chạy được&quot;.</li><li><strong>Có ít nhất 1 phép đo năng lực không phụ thuộc AI</strong> (unaided check) — ví dụ bảo vệ miệng ngắn/giải trình code trực tiếp — để tránh tình trạng nộp sản phẩm AI làm hộ mà sinh viên không hiểu, nhất quán với rủi ro &quot;cognitive offloading&quot; đã nêu ở review giáo dục AI trước đó của AI4W (xem Mục 10, tài liệu tham khảo). Từ v0.3.0, buổi này là <strong>demo công khai trước cả lớp</strong> (không chỉ riêng GV) — xem Mục 6.4.</li><li><strong>Dùng lại hạ tầng <code>ktpmud-project</code> hiện có</strong>, không tạo cổng nộp bài mới: <code>validate_submission.py</code>, <code>CODEOWNERS</code>, kiểm tra cách ly 1-nhóm-1-thư-mục. Chỉ thêm case-study slug mới + schema submission riêng cho BKT (khác CS-1.8 vì không cần SRS/C4 đầy đủ như đồ án PBL).</li></ol><h2 id="_4-case-study-registry-—-vi-tri-đe-xuat" tabindex="-1">4. Case study registry — vị trí đề xuất <a class="header-anchor" href="#_4-case-study-registry-—-vi-tri-đe-xuat" aria-label="Permalink to &quot;4. Case study registry — vị trí đề xuất&quot;">​</a></h2><p>Thêm 1 domain mới trong <code>docs/data/case_studies/</code>, tách khỏi 7 domain lâm sàng/ngoài-y-tế hiện có, để không trộn 2 loại case study khác bản chất:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/data/case_studies/</span></span>
<span class="line"><span>└── bai_kiem_tra_hackathon/</span></span>
<span class="line"><span>    ├── _domain.json</span></span>
<span class="line"><span>    ├── may_day_sprint.json       (BKT-1, slug: may_day_sprint)</span></span>
<span class="line"><span>    └── hoang_mai_toan.json       (BKT-2, slug: hoang_mai_toan)</span></span></code></pre></div><p>Không dùng lại slug <code>may_day</code> đã có (CS-1) — dùng <code>may_day_sprint</code> để tránh <code>ktpmud-project</code> hiểu nhầm là cùng 1 đề bài với CS-1 PBL 10-12 tuần.</p><h2 id="_5-bkt-1-track-a-dr-may-day-—-rule-engine-sprint-2-3-tuan" tabindex="-1">5. BKT-1 (Track A): Dr May Day — &quot;Rule Engine Sprint&quot; (2-3 tuần) <a class="header-anchor" href="#_5-bkt-1-track-a-dr-may-day-—-rule-engine-sprint-2-3-tuan" aria-label="Permalink to &quot;5. BKT-1 (Track A): Dr May Day — &quot;Rule Engine Sprint&quot; (2-3 tuần)&quot;">​</a></h2><h3 id="_5-1-ly-do-chon-đung-lat-cat-nay-khong-dung-ca-he-thong-cs-1" tabindex="-1">5.1. Lý do chọn đúng lát cắt này, không dùng cả hệ thống CS-1 <a class="header-anchor" href="#_5-1-ly-do-chon-đung-lat-cat-nay-khong-dung-ca-he-thong-cs-1" aria-label="Permalink to &quot;5.1. Lý do chọn đúng lát cắt này, không dùng cả hệ thống CS-1&quot;">​</a></h3><p>Toàn bộ CS-1 (SRS + CSDL + Rule Engine + AI module + UI + CI) không khả thi trong 1-2 tuần. Chọn đúng <strong>một module đã có đặc tả hoàn chỉnh, tất định, kiểm thử được độc lập</strong>: Rule Engine cảnh báo phản vệ WAO/EAACI — đã có sẵn đặc tả đủ chi tiết trong <code>docs/do_an_mon_hoc.md</code> Mục 2 và 4.1 (dùng lại nguyên văn, không soạn mới, tránh hai nguồn đặc tả cho cùng 1 logic).</p><p><strong>Đã tạo repo skeleton khởi động (02/11/2026):</strong><a href="https://github.com/fossbk-spec/ktpmud-bkt-ruleengine-starter" target="_blank" rel="noreferrer"><code>fossbk-spec/ktpmud-bkt-ruleengine-starter</code></a> (PUBLIC, Python/<code>pytest</code>) — khung project rỗng (<code>rule_engine/classifier.py</code> dạng stub, <code>tests/</code>, CI chạy <code>pytest</code>), đã chạy thử thật (<code>pytest</code> pass) trước khi công bố. Sinh viên fork repo này để bắt đầu, đỡ tốn thời gian setup trong 2-3 tuần ngắn, đúng nguyên tắc &quot;đề bài cung cấp trước&quot;.</p><h3 id="_5-2-đe-bai-cung-cap-truoc-khong-đoi-trong-luc-thi" tabindex="-1">5.2. Đề bài (cung cấp trước, không đổi trong lúc thi) <a class="header-anchor" href="#_5-2-đe-bai-cung-cap-truoc-khong-đoi-trong-luc-thi" aria-label="Permalink to &quot;5.2. Đề bài (cung cấp trước, không đổi trong lúc thi)&quot;">​</a></h3><ul><li>Input: form triệu chứng cấp cứu (mã hoá sẵn, Zero PII — <code>DMD-TEST-xxx</code>).</li><li>Logic: phân loại 3 mức nguy cơ theo chuẩn WAO/EAACI (tham chiếu đúng bảng Mục 1 &quot;NGUYÊN TẮC AN TOÀN BẮT BUỘC&quot; của <code>do_an_mon_hoc.md</code>).</li><li>Ràng buộc: rule-based thuần tuý (không Deep Learning), latency &lt; 100ms, Audit Trail <code>[Timestamp, User_UUID, Action_Type, Status]</code>.</li><li><strong>MVP bắt buộc:</strong> 1 API/CLI nhận input mẫu, trả đúng mức nguy cơ + log audit; có bộ test tự động (≥ 1 ca mỗi mức nguy cơ) chứng minh logic đúng.</li><li><strong>Chính sách AI:</strong> <code>ai-allowed</code> — sinh viên được dùng AI viết code/test, nhưng phải bảo vệ miệng ngắn (5-10 phút) giải thích đúng logic rule đã cài.</li></ul><h3 id="_5-3-thoi-luong-2-3-tuan-tuan-1-3-cua-pbl-xem-muc-3-3" tabindex="-1">5.3. Thời lượng: 2-3 tuần (Tuần 1-3 của PBL, xem Mục 3.3) <a class="header-anchor" href="#_5-3-thoi-luong-2-3-tuan-tuan-1-3-cua-pbl-xem-muc-3-3" aria-label="Permalink to &quot;5.3. Thời lượng: 2-3 tuần (Tuần 1-3 của PBL, xem Mục 3.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tuần</th><th>Việc</th></tr></thead><tbody><tr><td>Đầu Tuần 1</td><td>Công bố đề bài + data dictionary + acceptance criteria + <strong>bộ test ẩn chưa công bố</strong> (Mục 6.4)</td></tr><tr><td>Tuần 1–2</td><td>Nhóm tự làm, có thể hỏi TA qua kênh chung (không sửa đề); nhóm chọn Track A không song song làm Track B</td></tr><tr><td>Đầu/giữa Tuần 3 (GV chốt ngày cụ thể)</td><td>Nộp PR theo đúng quy trình <code>ktpmud-project</code> hiện có</td></tr><tr><td>Cuối Tuần 3</td><td>Demo công khai trước lớp + bảo vệ miệng (unaided check) + chấm + công bố leaderboard/giải (Mục 6.4)</td></tr></tbody></table><h2 id="_6-bkt-2-track-b-vuon-toan-lop-3-—-them-1-ky-nang-moi-2-3-tuan" tabindex="-1">6. BKT-2 (Track B): Vườn Toán Lớp 3 — &quot;Thêm 1 kỹ năng mới&quot; (2-3 tuần) <a class="header-anchor" href="#_6-bkt-2-track-b-vuon-toan-lop-3-—-them-1-ky-nang-moi-2-3-tuan" aria-label="Permalink to &quot;6. BKT-2 (Track B): Vườn Toán Lớp 3 — &quot;Thêm 1 kỹ năng mới&quot; (2-3 tuần)&quot;">​</a></h2><blockquote><p><strong>Thay đổi so với v0.1.0:</strong> app đích đổi từ <code>hoang-mai-math</code> sang <code>math3a2</code> (&quot;Vườn Toán Lớp 3&quot;). Lý do và đối chiếu chi tiết nằm ở <code>docs/reviews/KTPMUD_Hackathon_CaseStudy_AppChoice_Review_v1.0.0_20261101.md</code>. Tên case study trong registry vẫn giữ <code>hoang_mai_toan</code> (xem Mục 4) vì cả hai app đều là sản phẩm của Trường Tiểu học Hoàng Mai — chỉ đổi app bên dưới, không đổi tên hiển thị.</p></blockquote><h3 id="_6-1-vi-sao-chon-math3a2-khong-dung-hoang-mai-math" tabindex="-1">6.1. Vì sao chọn math3a2, không dùng hoang-mai-math <a class="header-anchor" href="#_6-1-vi-sao-chon-math3a2-khong-dung-hoang-mai-math" aria-label="Permalink to &quot;6.1. Vì sao chọn math3a2, không dùng hoang-mai-math&quot;">​</a></h3><p>Hai lần đánh giá độc lập của Codex (<code>codex -p lean</code>, lần 1 so A/B, lần 2 thêm app thứ 3) cùng kết luận: <code>hoang-mai-math</code> an toàn về dữ liệu (private, tự nhận &quot;teacher-demo — DEMO ONLY&quot;) nhưng <strong>kiến trúc quá nặng cho 1-2 tuần</strong> (Next.js + TypeScript + Prisma + knowledge graph/template validator cho <code>build-bank.ts</code>). <code>math3a2</code> (Express + SQLite + vanilla JS, có sẵn hướng dẫn <code>HUONG-DAN-THEM-BAI.md</code>) có ngưỡng vào thấp hơn nhiều, phù hợp khung 1-2 tuần hơn. Claude đã tự kiểm chứng lại từng claim này (đọc trực tiếp <code>package.json</code>, <code>README.md</code> của cả hai repo) trước khi chấp thuận kết luận.</p><p><strong>Rủi ro dữ liệu — ĐÃ GIẢI QUYẾT bằng repo starter riêng (02/11/2026), không còn sửa <code>math3a2</code> trực tiếp nữa.</strong> <code>math3a2</code> là repo <strong>PUBLIC</strong>; khi dọn dữ liệu để tạo starter, phát hiện vấn đề <strong>nghiêm trọng hơn đánh giá ban đầu</strong>: tên + <strong>ảnh thật</strong> của giáo viên (<code>fullName: &quot;Cô Hoàng Hương...&quot;</code>, avatar <code>teacher-hoang-huong.jpg</code> — ảnh chân dung thật, đã xem trực tiếp để xác nhận) gắn với tài khoản <code>giaovien01</code> không chỉ nằm ở <code>data/seed.json</code>, mà còn <strong>hard-code làm giá trị mặc định (fallback)</strong> trong <code>navbar.js</code>, <code>sidebar.js</code>, 9 file HTML tĩnh khác, và bị <code>server/db.js</code> <strong>tự ghi đè vào DB mỗi lần khởi động server</strong>. Vì mức độ lan rộng này, phương án &quot;chỉ sửa 1 trường trong <code>math3a2</code>&quot; (v0.2.0–v0.4.0) không còn đủ — đã đổi sang phương án sạch hơn:</p><blockquote><p><strong>Đã thực hiện:</strong> tạo repo mới <a href="https://github.com/fossbk-spec/ktpmud-bkt-vuontoan-starter" target="_blank" rel="noreferrer"><code>fossbk-spec/ktpmud-bkt-vuontoan-starter</code></a> (PUBLIC) — snapshot đóng băng của <code>math3a2</code> tại 1 thời điểm, <strong>lịch sử git reset về 1 commit sạch</strong> (không mang theo lịch sử cũ), toàn bộ tên/ảnh thật đã quét và thay bằng dữ liệu hư cấu trên <strong>mọi</strong> file (không chỉ <code>data/seed.json</code>) — đã xác minh trực tiếp trên GitHub sau khi push, không còn dấu vết. Sinh viên làm việc trên fork của repo starter này, <strong>không bao giờ đụng tới <code>math3a2</code> thật</strong> — giải quyết dứt điểm rủi ro, không cần rewrite lịch sử git của <code>math3a2</code> (tránh thao tác rủi ro cao trên hệ thống đang chạy production).</p></blockquote><h3 id="_6-2-đe-bai-cung-cap-truoc" tabindex="-1">6.2. Đề bài (cung cấp trước) <a class="header-anchor" href="#_6-2-đe-bai-cung-cap-truoc" aria-label="Permalink to &quot;6.2. Đề bài (cung cấp trước)&quot;">​</a></h3><ul><li>Cung cấp: repo starter <a href="https://github.com/fossbk-spec/ktpmud-bkt-vuontoan-starter" target="_blank" rel="noreferrer"><code>fossbk-spec/ktpmud-bkt-vuontoan-starter</code></a> (kiến trúc Express/<code>better-sqlite3</code>, <code>data/seed.json</code>, <code>server/api.js</code>, hướng dẫn thêm bài <code>HUONG-DAN-THEM-BAI.md</code> — giống hệt <code>math3a2</code> về kiến trúc, nhưng đã dọn sạch dữ liệu thật và đóng băng không đổi trong lúc thi).</li><li>Yêu cầu: thêm <strong>1 kỹ năng Toán mới</strong>. Đã kiểm tra trực tiếp <code>data/seed.json</code>: repo hiện có đủ 81 bài, toàn bộ chương trình SGK Toán 3 Kết nối tri thức — không còn &quot;nội dung SGK còn thiếu&quot; để thêm nguyên vẹn. Vì vậy &quot;kỹ năng mới&quot; ở đây là <strong>1 dạng bài/kiểu câu hỏi mới</strong> áp dụng lại trên nội dung đã có, không phải thêm chương Toán mới — mặc định đề xuất: <em>&quot;Ước lượng kết quả trước khi tính đúng&quot;</em> trên bộ bảng nhân/chia đã có (xem Mục 10 điểm 3; GV có thể đổi sang kỹ năng khác). Theo đúng kiến trúc sẵn có — không viết lại hệ thống, <strong>không sửa <code>server/auth.js</code>/session/tài khoản/triển khai</strong>.</li><li><strong>Làm trên fork của repo starter</strong> (không phải <code>math3a2</code> thật) — vì vậy rủi ro &quot;đụng production/tài khoản thật&quot; không còn tồn tại theo thiết kế, không chỉ dựa vào quy ước &quot;không được làm&quot; như phương án cũ.</li><li><strong>MVP bắt buộc:</strong> kỹ năng mới chạy được qua <code>npm start</code>, có câu hỏi/bài mới hiển thị và chấm đúng qua giao diện hoặc API. <code>math3a2</code> <strong>hiện chưa có script test tự động</strong> (khác với giả định ban đầu dựa trên <code>hoang-mai-math</code> có <code>bank:build</code>/test sẵn) — vì vậy mỗi nhóm phải <strong>tự viết tối thiểu 1 bộ test tự động</strong> (ví dụ <code>node --test</code>, hoặc script smoke-test gọi API) cho đúng kỹ năng mới thêm, coi đây là một phần MVP, nhất quán với TDD ở Ch.7.</li><li><strong>Chính sách AI:</strong> <code>ai-allowed</code>, cùng yêu cầu khai báo + bảo vệ miệng như BKT-1.</li></ul><h3 id="_6-3-thoi-luong-2-3-tuan-cung-cua-so-tuan-1-3-voi-track-a-xem-muc-3-3" tabindex="-1">6.3. Thời lượng: 2-3 tuần (cùng cửa sổ Tuần 1-3 với Track A, xem Mục 3.3) <a class="header-anchor" href="#_6-3-thoi-luong-2-3-tuan-cung-cua-so-tuan-1-3-voi-track-a-xem-muc-3-3" aria-label="Permalink to &quot;6.3. Thời lượng: 2-3 tuần (cùng cửa sổ Tuần 1-3 với Track A, xem Mục 3.3)&quot;">​</a></h3><p>Tuần 1: đọc kiến trúc thật trên fork riêng, thiết kế kỹ năng mới, viết test trước (TDD, đúng Ch.7). Tuần 2–3: hoàn thiện, tích hợp, nộp PR, demo công khai + bảo vệ miệng (Mục 6.4).</p><h3 id="_6-4-yeu-to-canh-tranh-va-gamification-ap-dung-cho-ca-track-a-va-track-b" tabindex="-1">6.4. Yếu tố cạnh tranh và Gamification (áp dụng cho CẢ Track A và Track B) <a class="header-anchor" href="#_6-4-yeu-to-canh-tranh-va-gamification-ap-dung-cho-ca-track-a-va-track-b" aria-label="Permalink to &quot;6.4. Yếu tố cạnh tranh và Gamification (áp dụng cho CẢ Track A và Track B)&quot;">​</a></h3><p>Quyết định 02/11/2026: áp dụng đồng thời 6 cơ chế dưới đây để tăng tính hấp dẫn/cạnh tranh, nhưng <strong>tất cả đều là điểm cộng/bonus</strong>, không thay thế tiêu chí pass/fail gốc (MVP + hiểu bài qua bảo vệ miệng, Mục 3 điểm 6-7) — tránh lệch trọng tâm sang &quot;ai trình diễn giỏi hơn&quot; thay vì &quot;ai làm đúng và hiểu bài&quot;.</p><ol><li><strong>Đa giải theo hạng mục</strong>, không chỉ 1 giải nhất — mỗi track có giải riêng: <ul><li>Track A: &quot;Rule Engine nhanh nhất&quot; (benchmark latency), &quot;Coverage test cao nhất&quot;, &quot;Code sạch nhất&quot; (static analysis/lint).</li><li>Track B: &quot;Kỹ năng Toán sáng tạo nhất&quot; (GV chấm chủ quan), &quot;Coverage test cao nhất&quot;, &quot;Code sạch nhất&quot;.</li></ul></li><li><strong>Leaderboard công khai lúc demo</strong>: hiển thị điểm định lượng (latency, % test pass, coverage) của các nhóm ngay trong buổi demo cuối Tuần 3 — dùng <strong>tên nhóm/alias</strong>, không dùng tên thật sinh viên (nhất quán với nguyên tắc ẩn danh đã áp dụng ở hoang-mai-math/case study khác).</li><li><strong>Demo công khai trước cả lớp</strong>: thay bảo vệ miệng riêng với GV bằng buổi trình bày trước các nhóm khác — vừa tăng động lực (áp lực xã hội tích cực), vừa làm unaided-check đáng tin hơn (cả lớp cùng nghe, không chỉ 1 người chấm).</li><li><strong>Peer review có điểm cộng nhỏ</strong>: mỗi nhóm nhận xét ≥1 PR của nhóm khác (cùng track hoặc khác track) được cộng điểm nhẹ — GV/TA cần đặt ngưỡng &quot;nhận xét có thực chất&quot; (không chỉ &quot;LGTM&quot;) để tránh bị lợi dụng chỉ để lấy điểm.</li><li><strong>Benchmark trên bộ test ẩn — chỉ Track A (Rule Engine)</strong>: một bộ case không công bố trước, dùng để so điểm công bằng giữa các nhóm, chống học vẹt/copy đáp án. <strong>Điều kiện bắt buộc</strong>: bộ test ẩn này phải được đối chiếu đúng bảng phân loại WAO/EAACI đã có trong <code>do_an_mon_hoc.md</code> Mục 2/4.1, do GV xác nhận trước khi dùng — không tự suy diễn ngưỡng/case mới chưa được xác nhận y khoa (đúng nguyên tắc đã áp dụng ở Case Study Chương 2 về việc không tự đặt ngưỡng lâm sàng). Track B không áp dụng mục này (không có rủi ro tương tự).</li><li><strong>Đăng bài nổi bật vào <code>ktpmud-book</code></strong>: 1-2 case study xuất sắc mỗi track (GV chọn, không tự động theo leaderboard) được viết lại thành trang &quot;Hall of Fame&quot;, <strong>ẩn danh theo tên nhóm</strong>, publish công khai — tạo sản phẩm sinh viên có thể đưa vào CV/portfolio.</li></ol><h2 id="_7-cap-nhat-bai-giang-can-lam" tabindex="-1">7. Cập nhật bài giảng cần làm <a class="header-anchor" href="#_7-cap-nhat-bai-giang-can-lam" aria-label="Permalink to &quot;7. Cập nhật bài giảng cần làm&quot;">​</a></h2><p>Không viết lại toàn bộ 12 chương. Đề xuất cập nhật tối thiểu, đúng phạm vi:</p><ol><li><strong><code>docs/syllabus.md</code> và trang mới <code>docs/bai_kiem_tra_hackathon.md</code></strong> — thêm mục giới thiệu khung BKT song song với đồ án PBL, không gộp vào <code>do_an_mon_hoc.md</code> (tránh sinh viên nhầm 2 khung làm 1).</li><li><strong>Chương 9 (AI-Augmented SE)</strong> — bổ sung 1 mục ngắn về chính sách khai báo sử dụng AI khi làm bài kiểm tra (đúng tinh thần <code>9.2.1 Human-in-the-Loop</code> đã có, áp dụng cụ thể cho BKT).</li><li><strong>Không đụng Chương 4</strong> — hồ sơ thẩm định <code>tham_dinh/CH04</code> hiện ghi &quot;chưa đạt nghiệm thu&quot; (xem tài liệu tham khảo); BKT không phụ thuộc nội dung Chương 4 phải sửa xong trước, nên không chặn tiến độ BKT.</li></ol><h2 id="_8-trinh-tu-trien-khai-theo-pr" tabindex="-1">8. Trình tự triển khai theo PR <a class="header-anchor" href="#_8-trinh-tu-trien-khai-theo-pr" aria-label="Permalink to &quot;8. Trình tự triển khai theo PR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PR</th><th>Repo</th><th>Nội dung</th><th>Tiêu chí thoát</th></tr></thead><tbody><tr><td>BKT-PR-0</td><td>KTPMUD</td><td>Trang <code>bai_kiem_tra_hackathon.md</code>, domain + 2 case JSON, cập nhật <code>syllabus.md</code></td><td>Trang build được qua <code>npm run docs:build</code>, audit không báo lỗi</td></tr><tr><td>BKT-PR-1</td><td>ktpmud-project</td><td>Thêm 2 slug (<code>may_day_sprint</code>, <code>hoang_mai_toan</code>) vào validator + schema submission rút gọn (không yêu cầu SRS/C4 đầy đủ như CS-1..8)</td><td>Submission mẫu giả lập PASS</td></tr><tr><td>BKT-PR-2</td><td>KTPMUD</td><td>Mục AI-use policy ngắn trong Chương 9</td><td>Không phá cấu trúc 6-phần chuẩn của chương</td></tr><tr><td>BKT-PR-2b</td><td>KTPMUD</td><td>Soạn bộ test ẩn cho Track A, đối chiếu bảng WAO/EAACI trong <code>do_an_mon_hoc.md</code> (Mục 6.4 điểm 5)</td><td>GV xác nhận từng case đúng bảng phân loại trước khi khóa đề</td></tr><tr><td>BKT-PR-3</td><td>KTPMUD/ktpmud-project</td><td>Chạy thử BKT-1 (Dr May Day Sprint) với 1 nhóm/dữ liệu giả lập trước khi mở thật</td><td>Pipeline nộp bài chạy hết, phát hiện đúng lỗi giả lập đưa vào</td></tr><tr><td><s>(tiên quyết BKT-PR-4)</s> ✅ XONG</td><td><code>ktpmud-bkt-vuontoan-starter</code> (repo mới)</td><td><s>Thay tên giáo viên thật</s> → đã tạo hẳn repo starter riêng, dọn sạch toàn bộ tên+ảnh thật (Mục 6.1)</td><td>✅ Đã xác minh trên GitHub: không còn dấu vết dữ liệu thật</td></tr><tr><td>BKT-PR-4</td><td>KTPMUD/ktpmud-project</td><td>Chạy thử BKT-2 (Vườn Toán Lớp 3, dùng <code>ktpmud-bkt-vuontoan-starter</code>) tương tự</td><td>Tương tự</td></tr><tr><td>BKT-PR-5 (sau khi chấm)</td><td>KTPMUD</td><td>Trang &quot;Hall of Fame&quot; đăng 1-2 case study nổi bật/track, ẩn danh theo tên nhóm (Mục 6.4 điểm 6)</td><td>GV chọn bài, xác nhận không còn thông tin định danh thật trước khi publish</td></tr></tbody></table><h2 id="_9-rui-ro-va-kiem-soat" tabindex="-1">9. Rủi ro và kiểm soát <a class="header-anchor" href="#_9-rui-ro-va-kiem-soat" aria-label="Permalink to &quot;9. Rủi ro và kiểm soát&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rủi ro</th><th>Kiểm soát</th></tr></thead><tbody><tr><td>Sinh viên nhầm BKT với đồ án PBL CS-1..8</td><td>Trang riêng, slug riêng, không dùng lại tên <code>may_day</code></td></tr><tr><td>Nộp sản phẩm AI làm hộ hoàn toàn</td><td>Bảo vệ miệng bắt buộc (unaided check) tại cả 2 BKT</td></tr><tr><td>MVP &quot;ăn gian&quot; (demo giả, không chạy thật)</td><td>Tiêu chí MVP gắn với lệnh chạy thật có sẵn trong repo (<code>npm test</code>, <code>pytest</code>), không chấp nhận chỉ có slide</td></tr><tr><td><s>math3a2 là repo thật đang phát triển — sinh viên code đè lên nhánh chính hoặc đụng dữ liệu lớp thật</s> ✅ ĐÃ LOẠI BỎ</td><td>Sinh viên dùng repo starter <code>ktpmud-bkt-vuontoan-starter</code> (snapshot đóng băng, không kết nối <code>math3a2</code>/Railway) — không còn khả năng đụng tới app thật theo thiết kế (Mục 6.1)</td></tr><tr><td><s><code>data/seed.json</code> của math3a2 có tên giáo viên thật</s> ✅ ĐÃ XỬ LÝ</td><td>Đã tạo <code>ktpmud-bkt-vuontoan-starter</code>, quét và thay toàn bộ tên+ảnh thật (không chỉ seed.json — còn ở nhiều file JS/HTML khác), xác minh sạch trên GitHub (Mục 6.1)</td></tr><tr><td>math3a2 (và starter kế thừa từ nó) chưa có script test tự động sẵn</td><td>MVP yêu cầu nhóm tự viết tối thiểu 1 bộ test cho kỹ năng mới (Mục 6.2), không dựa vào <code>npm test</code> có sẵn</td></tr><tr><td>Thời lượng 2-3 tuần không đủ nếu đề quá rộng</td><td>Đã chốt phạm vi hẹp (1 module Rule Engine; 1 kỹ năng Toán), không phải toàn hệ thống</td></tr><tr><td>BKT-1 trùng nội dung Rule Engine với Sprint PBL của CS-1 → sinh viên copy chéo giữa 2 bài</td><td>Đặt cửa sổ BKT ở Tuần 1-3, trước khi PBL bắt đầu Sprint Rule Engine (Tuần 4+, xem Mục 3.3)</td></tr><tr><td>Chạy song song PBL + BKT có thể làm quá tải sinh viên trong Tuần 1-3</td><td>Phạm vi BKT đã hẹp (1 module/1 kỹ năng); GV cần theo dõi tải thực tế ở lần chạy pilot đầu tiên</td></tr><tr><td>Leaderboard/demo công khai tạo áp lực xã hội cho nhóm yếu</td><td>Dùng tên nhóm/alias, không tên thật; mọi yếu tố cạnh tranh chỉ là điểm cộng, không phải điểm liệt (Mục 6.4)</td></tr><tr><td>Bộ test ẩn Track A sai logic lâm sàng nếu không đối chiếu kỹ</td><td>Bắt buộc GV xác nhận từng case đúng bảng WAO/EAACI trước khi dùng (BKT-PR-2b)</td></tr><tr><td>Peer review bị lợi dụng chỉ để lấy điểm cộng (nhận xét hình thức)</td><td>GV/TA đặt ngưỡng &quot;nhận xét có thực chất&quot;, có thể spot-check</td></tr></tbody></table><h2 id="_10-quyet-đinh-chot-02-11-2026-claude-quyet-theo-yeu-cau-nguoi-dung" tabindex="-1">10. Quyết định (chốt 02/11/2026, Claude quyết theo yêu cầu người dùng) <a class="header-anchor" href="#_10-quyet-đinh-chot-02-11-2026-claude-quyet-theo-yeu-cau-nguoi-dung" aria-label="Permalink to &quot;10. Quyết định (chốt 02/11/2026, Claude quyết theo yêu cầu người dùng)&quot;">​</a></h2><p>Tất cả 7 điểm trước đây để mở nay đã chốt. 1 điểm (đánh dấu ⚠️) là <strong>mặc định cần GV xác nhận lại với lịch thật</strong>, không phải dữ kiện Claude có thể tự xác minh.</p><ol><li>⚠️ <strong>Lịch/nhánh PBL:</strong> mặc định dùng nhánh &quot;MayDay-Sim&quot; đơn giản (Sprint 2 Rule Engine ở Tuần 4-6, theo <code>syllabus.md</code> dòng 399) làm căn cứ đặt cửa sổ BKT ở Tuần 1-3. Nếu lớp thực tế dạy nhánh &quot;Tích hợp thật&quot; (Sprint Rule Engine ở Tuần 6-7) hoặc tổng số tuần khác 10-12, <strong>GV cần xác nhận lại</strong> Tuần 1-3 vẫn còn an toàn (trước khi sinh viên đụng code Rule Engine PBL) — đây là dữ kiện lịch học thật, Claude không thể tự xác minh thay.</li><li><strong>Demo công khai:</strong> toàn bộ nhóm cùng trình bày, nhưng GV/lớp có thể chất vấn <strong>bất kỳ thành viên nào, không báo trước ai</strong> — kết hợp cả 2 phương án gốc: giữ không khí teamwork công khai nhưng vẫn đủ bất ngờ để chống &quot;chỉ 1 người học bài&quot;.</li><li><strong>Kỹ năng Toán cụ thể cho Track B:</strong> đã kiểm tra trực tiếp <code>math3a2/data/seed.json</code> — repo hiện có <strong>đủ 81 bài, toàn bộ chương trình SGK Kết nối tri thức Toán 3</strong> (Chủ đề 1–16), nên không còn &quot;bài học SGK còn thiếu&quot; để thêm nguyên vẹn. Đề xuất mặc định: thêm <strong>1 dạng bài luyện tập mới</strong> (không phải nội dung SGK mới) — <em>&quot;Ước lượng kết quả trước khi tính đúng&quot;</em> (vd làm tròn rồi đoán khoảng kết quả phép nhân/chia, trước khi bấm xem đáp án chính xác) — áp dụng lại trên bộ bảng nhân/chia đã có (Chủ đề 2, bài 9-14), không thêm nội dung toán mới, chỉ thêm 1 kiểu câu hỏi/kỹ năng tư duy mới đúng đề bài gốc &quot;thêm 1 kỹ năng Toán mới&quot;. <strong>GV có thể đổi sang kỹ năng khác nếu có ý tưởng phù hợp hơn</strong> — đây là gợi ý mặc định, không phải quyết định chuyên môn sư phạm cuối cùng (ngoài năng lực Claude tự quyết thay GV).</li><li><strong>Phạm vi mở:</strong> pilot 1-2 nhóm/track trước, đúng tiêu chí thoát đã đặt ở BKT-PR-3/4 — chỉ mở toàn lớp sau khi pilot chạy hết pipeline không lỗi.</li><li>✅ <strong>XONG (02/11/2026):</strong> thay vì sửa <code>math3a2/data/seed.json</code> trực tiếp, Claude đã tạo repo starter riêng <code>ktpmud-bkt-vuontoan-starter</code> (PUBLIC), quét và thay toàn bộ tên+ảnh thật của giáo viên trên mọi file (phát hiện vấn đề lan rộng hơn chỉ <code>seed.json</code> — xem Mục 6.1), xác minh sạch trên GitHub sau khi push. Không cần sửa/rewrite lịch sử <code>math3a2</code> thật nữa.</li><li><strong>Soạn bộ test ẩn Track A:</strong> Claude soạn khung (đối chiếu đúng bảng WAO/EAACI trong <code>do_an_mon_hoc.md</code> Mục 2/4.1), GV xác nhận lại từng case đúng/đủ trước khi khóa đề — đúng BKT-PR-2b.</li><li><strong>Tiêu chí Hall of Fame:</strong> 1 bài/track (không phải 2), GV chọn (không tự động theo leaderboard, vì Track B cần đánh giá tính sáng tạo chủ quan), publish <strong>ngay sau khi chấm</strong> (không dồn cuối kỳ) để giữ động lực tức thì.</li></ol><h2 id="_11-tai-lieu-tham-khao" tabindex="-1">11. Tài liệu tham khảo <a class="header-anchor" href="#_11-tai-lieu-tham-khao" aria-label="Permalink to &quot;11. Tài liệu tham khảo&quot;">​</a></h2><ul><li><code>KTPMUD/docs/do_an_mon_hoc.md</code> (đặc tả Rule Engine WAO/EAACI dùng lại cho BKT-1)</li><li><code>KTPMUD/docs/syllabus.md</code>, <code>KTPMUD/docs/nop_bai.md</code></li><li><code>KTPMUD/docs/data/case_studies/da_lieu_mien_dich/may_day.json</code></li><li><code>KTPMUD/tham_dinh/CH04/README.md</code> (trạng thái &quot;chưa đạt&quot; — lý do không đụng Ch.4 trong phạm vi này)</li><li><code>ktpmud-project/scripts/validate_submission.py</code>, <code>ktpmud-project/CONTRIBUTING.md</code></li><li><code>math3a2/README.md</code>, <code>math3a2/package.json</code>, <code>math3a2/HUONG-DAN-THEM-BAI.md</code> (kiến trúc gốc tham khảo — sinh viên dùng bản starter đã dọn, không dùng repo này trực tiếp)</li><li><a href="https://github.com/fossbk-spec/ktpmud-bkt-vuontoan-starter" target="_blank" rel="noreferrer">https://github.com/fossbk-spec/ktpmud-bkt-vuontoan-starter</a> (repo starter Track B thật, sinh viên dùng repo này)</li><li><a href="https://github.com/fossbk-spec/ktpmud-bkt-ruleengine-starter" target="_blank" rel="noreferrer">https://github.com/fossbk-spec/ktpmud-bkt-ruleengine-starter</a> (repo skeleton Track A thật, sinh viên dùng repo này)</li><li><code>docs/reviews/KTPMUD_Hackathon_CaseStudy_AppChoice_Review_v1.0.0_20261101.md</code> (căn cứ đổi app, 2 vòng đánh giá Codex + tự kiểm chứng Claude)</li><li><code>hoang-mai-math/README.md</code> (phương án bị loại ở v0.2.0; trạng thái teacher-demo, nguyên tắc đáp án tất định/AI chỉ hỗ trợ — vẫn tham khảo cho tinh thần thiết kế)</li><li><code>AI4W/docs/proposals/AI4W_Higher_Education_Profile_Teaching_Workflow_Proposal_v0.1.0_20261101.md</code> (khái niệm assessment mode ai-required/ai-allowed/ai-limited/ai-prohibited và unaided-performance check, tham khảo nguyên tắc không copy nguyên schema)</li><li><code>AI4W/docs/reviews/AI4W_Review_Lo_trinh_5_cap_do_AI_giang_vien_2026_v1.1.0_20261101.md</code> (bằng chứng cognitive offloading, Mục 10.3)</li></ul><h2 id="_12-changelog" tabindex="-1">12. Changelog <a class="header-anchor" href="#_12-changelog" aria-label="Permalink to &quot;12. Changelog&quot;">​</a></h2><h3 id="v0-5-0-—-02-11-2026" tabindex="-1">v0.5.0 — 02/11/2026 <a class="header-anchor" href="#v0-5-0-—-02-11-2026" aria-label="Permalink to &quot;v0.5.0 — 02/11/2026&quot;">​</a></h3><ul><li>Tạo 2 repo starter công khai mới thay vì sửa <code>math3a2</code> trực tiếp: <code>ktpmud-bkt-vuontoan-starter</code> (Track B, snapshot đóng băng đã dọn sạch dữ liệu thật) và <code>ktpmud-bkt-ruleengine-starter</code> (Track A, skeleton Python/pytest, đã chạy thử pass).</li><li>Phát hiện quan trọng khi dọn dữ liệu: tên+ảnh thật của giáo viên không chỉ ở <code>data/seed.json</code> mà còn hard-code trong nhiều file JS/HTML và bị server tự ghi đè vào DB — nghiêm trọng hơn đánh giá ở v0.2.0-v0.4.0. Đã quét và xác minh sạch 100% trên GitHub sau khi push.</li><li>Cập nhật Mục 5, 6.1, 6.2, 8, 9, 10 điểm 5, 11 để trỏ sang 2 repo mới thay vì <code>math3a2</code>/kế hoạch sửa trực tiếp.</li><li>Không còn cần rewrite lịch sử git của <code>math3a2</code> thật — rủi ro vận hành cao đã được loại bỏ bằng kiến trúc (sinh viên không bao giờ chạm vào repo thật), không chỉ dựa vào quy ước.</li></ul><h3 id="v0-4-0-—-02-11-2026" tabindex="-1">v0.4.0 — 02/11/2026 <a class="header-anchor" href="#v0-4-0-—-02-11-2026" aria-label="Permalink to &quot;v0.4.0 — 02/11/2026&quot;">​</a></h3><ul><li>Chốt toàn bộ 7 điểm còn mở ở Mục 10, theo yêu cầu người dùng &quot;quyết luôn các câu hỏi mở còn lại&quot; — xem Mục 10 mới.</li><li>Phát hiện và sửa: <code>math3a2/data/seed.json</code> đã có đủ 81 bài (toàn bộ SGK Toán 3), không còn nội dung thiếu — Mục 6.2 sửa lại thành &quot;thêm 1 dạng bài mới&quot; (mặc định: ước lượng kết quả), không phải &quot;thêm bài SGK còn thiếu&quot; như giả định sai ở v0.1.0-v0.3.0.</li><li>Mục 6.1: ghi rõ Claude sẽ thực hiện việc sửa <code>seed.json</code> của <code>math3a2</code>.</li><li>Mục 5.3/6.3: chốt hình thức demo — toàn nhóm trình bày, chất vấn ngẫu nhiên không báo trước.</li></ul><h3 id="v0-3-0-—-02-11-2026" tabindex="-1">v0.3.0 — 02/11/2026 <a class="header-anchor" href="#v0-3-0-—-02-11-2026" aria-label="Permalink to &quot;v0.3.0 — 02/11/2026&quot;">​</a></h3><ul><li>Thời lượng tăng 1-2 tuần → 2-3 tuần cho cả 2 track, theo quyết định người dùng; chạy song song với đồ án PBL (không tách riêng).</li><li>Thêm nguyên tắc: mỗi nhóm chỉ chọn 1 trong 2 track (Mục 3 điểm 2); đặt cửa sổ BKT ở Tuần 1-3 để tránh trùng Sprint Rule Engine của PBL (Mục 3 điểm 3, đối chiếu <code>syllabus.md</code>).</li><li>Thêm Mục 6.4: 6 cơ chế gamification/cạnh tranh (đa giải, leaderboard công khai, demo công khai thay bảo vệ miệng riêng, peer review có điểm cộng, bộ test ẩn cho Track A, Hall of Fame trên <code>ktpmud-book</code>) — tất cả là điểm cộng, không thay tiêu chí pass/fail gốc.</li><li>Thêm BKT-PR-2b (soạn bộ test ẩn, GV xác nhận đúng bảng WAO/EAACI) và BKT-PR-5 (đăng Hall of Fame) vào Mục 8.</li><li>Thêm 5 rủi ro mới vào Mục 9 (trùng nội dung PBL, quá tải song song, áp lực xã hội từ công khai, sai logic bộ test ẩn, peer review bị lợi dụng).</li><li>Mục 10: đánh dấu 3 điểm đã chốt, thêm 3 câu hỏi mở mới (xác nhận lịch thật, ai soạn bộ test ẩn, tiêu chí Hall of Fame).</li></ul><h3 id="v0-2-0-—-02-11-2026" tabindex="-1">v0.2.0 — 02/11/2026 <a class="header-anchor" href="#v0-2-0-—-02-11-2026" aria-label="Permalink to &quot;v0.2.0 — 02/11/2026&quot;">​</a></h3><ul><li>Mục 6 (BKT-2) viết lại: đổi app đích từ <code>hoang-mai-math</code> sang <code>math3a2</code>, theo kết quả 2 vòng đánh giá Codex + tự kiểm chứng của Claude (<code>docs/reviews/KTPMUD_Hackathon_CaseStudy_AppChoice_Review_v1.0.0_20261101.md</code>).</li><li>Thêm điều kiện tiên quyết bắt buộc: thay tên giáo viên thật trong <code>math3a2/data/seed.json</code> trước khi mở BKT-2 cho sinh viên (người dùng xác nhận trực tiếp đây là tên thật/tài khoản production thật).</li><li>Cập nhật MVP của BKT-2: <code>math3a2</code> chưa có script test tự động sẵn — mỗi nhóm phải tự viết tối thiểu 1 bộ test cho kỹ năng mới.</li><li>Thêm Mục 10.5 (câu hỏi mở): ai phụ trách và khi nào sửa <code>seed.json</code> của <code>math3a2</code>.</li></ul><h3 id="v0-1-0-—-01-11-2026" tabindex="-1">v0.1.0 — 01/11/2026 <a class="header-anchor" href="#v0-1-0-—-01-11-2026" aria-label="Permalink to &quot;v0.1.0 — 01/11/2026&quot;">​</a></h3><ul><li>Đề xuất đầu tiên: khung BKT song song với đồ án PBL, 2 case study cụ thể (Dr May Day Rule Engine Sprint, Hoàng Mai Toán), trình tự PR, rủi ro và việc cần người dùng quyết.</li></ul>`,61)])])}const m=n(i,[["render",a]]);export{l as __pageData,m as default};
